-- PBI-004: vehículos de un cliente. La patente se guarda en mayúsculas desde la API.
create table if not exists public.vehiculos (
  "Id_Vehiculos" integer generated by default as identity primary key,
  "Id_Personas" integer not null references public.personas("Id_Personas") on delete restrict,
  "Id_Tipos_Vehiculos" integer not null references public.tipos_vehiculos("Id_Tipos_Vehiculos") on delete restrict,
  "Patente" varchar(20) not null,
  "Marca" varchar(80) null,
  "Modelo" varchar(80) null,
  "Color" varchar(40) null,
  "Activo" boolean not null default true
);

create unique index if not exists ux_vehiculos_patente on public.vehiculos ("Patente");
create index if not exists ix_vehiculos_persona on public.vehiculos ("Id_Personas");
